document.addEventListener('DOMContentLoaded', function () {
  // lazy load
  setTimeout(function () {
    $('.js-bg').each(function () {
      $(this).css('background-image', 'url(' + $(this).data('bg') + ')');
    });
    $('.js-img').each(function () {
      $(this).attr('src', $(this).data('src'));
    });
  }, 200);
  // loader
  setTimeout(function () {
    $('body, ._body').removeClass('loaded');
    if ($('.wow').length) {
      new WOW().init();
    }
  }, 1000);
});

/* viewport width */
function viewport() {
  var e = window,
    a = 'inner';
  if (!('innerWidth' in window)) {
    a = 'client';
    e = document.documentElement || document.body;
  }
  return { width: e[a + 'Width'], height: e[a + 'Height'] };
}
/* viewport width */

(function () {
  $('.accordeon .accordeon-hide:not(.active)').hide();
  $('.accordeon .accordeon-hide')
    .prev()
    .click(function (e) {
      e.preventDefault();
      $(this)
        .parents('.accordeon')
        .find('.accordeon-hide')
        .not(this)
        .slideUp()
        .prev()
        .removeClass('active')
        .parent()
        .removeClass('active');
      $(this)
        .next()
        .not(':visible')
        .slideDown()
        .prev()
        .addClass('active')
        .parent()
        .addClass('active');
    });

  $('.footer .logo a').on('click', function (e) {
    $('html, body').animate({ scrollTop: 0 }, 1000);
    return false;
  });

  $('.tabs li a').click(function () {
    $(this).parents('.tab-wrap').find('.tab-cont').addClass('hide-tab');
    $(this).parent().siblings().removeClass('active');
    var id = $(this).attr('href');
    $(id).removeClass('hide-tab');
    $(this).parent().addClass('active');
    return false;
  });

  var $range = $('.js-range-slider');
  var $input = $('#monney');
  var instance;
  var min = 1000;
  var max = 60000;

  $range.ionRangeSlider({
    skin: 'round',
    type: 'single',
    min: min,
    max: max,
    from: 45000,
    hide_from_to: true,
    onStart: function (data) {
      $input.prop(
        'value',
        String(data.from).replace(/(\d)(?=(\d\d\d)+([^\d]|$))/g, '$1 ')
      );
    },
    onChange: function (data) {
      $input.prop(
        'value',
        String(data.from).replace(/(\d)(?=(\d\d\d)+([^\d]|$))/g, '$1 ')
      );
    },
  });

  instance = $range.data('ionRangeSlider');

  $input.on('input', function () {
    var val = $(this).prop('value');
    // validate
    if (val < min) {
      val = min;
    } else if (val > max) {
      val = max;
    }
    instance.update({
      from: val,
    });
  });
  $input.on('blur', function () {
    var val = $(this).prop('value');
    // validate
    if (val < min) {
      val = min;
      $(this).prop('value', val);
    } else if (val > max) {
      val = max;
      $(this).prop('value', val);
    }
  });
  if ($('#win_2').length) {
    $(document).on('mouseleave', function (e) {
      $.fancybox.open({
        src: '#win_2',
      });
      $(document).off('mouseleave');
    });
  }

  // svg timer
  if ($('.js-timer').length) {
    // Set the date we're counting down to
    var countDownDate = new Date().getTime() + 600000;

    // Update the count down every 1 second
    var x = setInterval(function () {
      // Get today's date and time
      var now = new Date().getTime();

      // Find the distance between now and the count down date
      var distance = countDownDate - now;

      // Time calculations for days, hours, minutes and seconds
      // var days = Math.floor(distance / (1000 * 60 * 60 * 24));
      // var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
      var seconds = Math.floor((distance % (1000 * 60)) / 1000);

      // let m = minutes + 1;
      // function pluralForm(n, forms) {
      // 	return forms[(n % 10 == 1 && n % 100 != 11 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2)];
      // }
      // document.querySelector(".js-amount-time").textContent = m + pluralForm(m, [" минута", " минуты", " минут"]);

      if (minutes < 10) {
        minutes = '0' + minutes;
      }
      if (seconds < 10) {
        seconds = '0' + seconds;
      }
      // Display the result in the element with id="demo"
      document.querySelector('.js-minutes').textContent = minutes;
      document.querySelector('.js-seconds').textContent = seconds;

      // If the count down is finished, write some text
      if (distance <= 1000) {
        countDownDate = new Date().getTime() + 600000;
      }

      600000;
    }, 1000);

    var svgPath = $('.step-timer-svg svg g').children('path, rect'),
      count = 59;

    var y = setInterval(function () {
      $(svgPath[count]).addClass('active');
      count = count - 1;
      if (count < 0) {
        count = 59;
        $(svgPath).removeClass('active');
      }
    }, 10000);
  }

  // Hamburger click
  $('.js-menu').on('click', function () {
    $(this).closest('body').toggleClass('active');
    return false;
  });

  $(document).mouseup(function (e) {
    // событие клика по веб-документу
    var div = $('.header'); // тут указываем ID элемента
    if (
      !div.is(e.target) && // если клик был не по нашему блоку
      div.has(e.target).length === 0
    ) {
      // и не по его дочерним элементам
      $('body').removeClass('active');
    }
  });

  // Process manipulation
  $('.js-process-prev').on('click', function (e) {
    e.preventDefault();
    var number = $(this).closest('body').attr('class').slice(-1);
    changeStep(+number - 1);
    moveStart();
  });

  $('.js-process').on('click', function (e) {
    e.preventDefault();
    var number = $(this).data('next');
    changeStep(+number + 1);
    moveStart();
  });

  if ($('.window-open_reg').length) {
    $('.window-open_reg .checkbox').on('change', function (e) {
      var btn = $(this).closest('.box-form').find('.btn');
      if ($(this).prop('checked')) {
        $(btn).removeClass('disabled');
      } else {
        $(btn).addClass('disabled');
      }
    });
  }

  function moveStart() {
    $('html, body').animate(
      {
        scrollTop: $('body').offset().top,
      },
      500
    );
  }

  function changeStep(indx) {
    $('body').removeClass('active_1 active_2 active_3 active_4 active_5');
    $('body').addClass('active_' + indx);
    if (indx === 4) {
      animateNumb($('.js-numbers'), 1);
      animateNumb($('.user-data-percent'), 2);
      setTimeout(function () {
        $('.btn-f').removeClass('disabled');
      }, 5000);
    } else {
      $('.btn-f').addClass('disabled');
    }
  }

  function animateNumb(target, type) {
    target.each(function () {
      $(this)
        .prop('Counter', $(this).data('start'))
        .animate(
          {
            Counter: $(this).data('finish'),
          },
          {
            duration: 5000,
            easing: 'swing',
            step: function (now, fx) {
              if (type == 1) {
                $(this).text(Math.ceil(now));
              } else if (type == 2) {
                $(this).attr('style', 'stroke-dashoffset : ' + Math.ceil(now));
              }
            },
          }
        );
    });
  }

  if ($('.js-styled').length) {
    $('.js-styled').styler();
  }
  setTimeout(function () {
    if ($('.jq-selectbox__dropdown ul').length) {
      $('.jq-selectbox__dropdown ul').mCustomScrollbar({
        axis: 'y',
        theme: 'dark-thin',
        autoExpandScrollbar: false,
        autoDraggerLength: false,
        advanced: { autoExpandHorizontalScroll: true },
      });
    }
  }, 1000);
})();

var handler = function () {
  var viewport_wid = viewport().width;
  var viewport_height = viewport().height;

  // if (viewport_wid <= 991) {

  // }
};

$(window).bind('load', handler);
$(window).bind('resize', handler);
